}

/**
 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const db = getDb();
  // The row count cannot be the sequence: moved issues leave retired numbers
  // behind. Seed the sequence from existing issue rows, then advance it
  // atomically on every allocation.
  db.run(sql`INSERT INTO issue_number_sequences (org_id, project_id, last_number)
    VALUES (${orgId}, ${projectId},
      (SELECT COALESCE(MAX(number), 0) + 1 FROM issues
       WHERE org_id = ${orgId} AND project_id = ${projectId}))
    ON CONFLICT (org_id, project_id) DO UPDATE SET last_number =
      max(issue_number_sequences.last_number,
        (SELECT COALESCE(MAX(number), 0) FROM issues
         WHERE org_id = ${orgId} AND project_id = ${projectId})) + 1`);
  const row = db
    .select({ value: issueNumberSequences.lastNumber })
    .from(issueNumberSequences)
